// [S4] Deterministic lab range status — RULE 4: code, never LLM judgement.
namespace FamilyVeda.Domain.Records;

public enum LabRangeStatus
{
    RangeUnavailable,
    BelowRange,
    WithinRange,
    AboveRange
}

/// <summary>
/// Classifies a lab value against the reference interval printed on the report.
/// The value and interval share one unit on <see cref="LabValue"/>, so no conversion happens here.
/// A missing bound yields <see cref="LabRangeStatus.RangeUnavailable"/>; a range is never invented.
/// </summary>
public static class LabRangeClassifier
{
    public static LabRangeStatus Classify(decimal value, decimal? referenceLow, decimal? referenceHigh)
    {
        if (referenceLow is null || referenceHigh is null || referenceLow > referenceHigh)
        {
            return LabRangeStatus.RangeUnavailable;
        }

        if (value < referenceLow) return LabRangeStatus.BelowRange;
        if (value > referenceHigh) return LabRangeStatus.AboveRange;
        return LabRangeStatus.WithinRange;
    }
}
